update nexora.modules set description='Programe em Python com foco em fundamentos, estruturas de dados, arquivos, tratamento de erros, ambientes, automação e consumo de APIs.' where course_id=(select id from nexora.courses where slug='programador-master') and position=7;
update nexora.lessons set objective='Explicar como o interpretador Python executa um script e preparar um fluxo simples de edição, execução e leitura de erros.',estimated_minutes=30,lab_type='python',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Um arquivo .py existe, mas ninguém sabe qual comando executá-lo nem qual versão está ativa."},{"type":"concept","title":"Python e o interpretador","body":"Python é uma linguagem interpretada: o runtime lê e executa o código. O arquivo .py é texto; a execução depende de um interpretador disponível no ambiente. Saber verificar versão, caminho e ambiente evita erros em que o código está correto, mas a máquina executa outro Python ou não encontra dependências. O ciclo básico é editar, executar, observar a saída e corrigir."},{"type":"mechanics","title":"Como aplicar","items":["Confirme a versão ativa.","Execute scripts a partir do diretório correto.","Leia traceback de baixo para cima.","Separe problema de ambiente de problema de código."]},{"type":"example","title":"Exemplo","body":"python --version\\npython app.py","language":"python"},{"type":"mistake","title":"Erro comum","body":"Instalar várias versões e pacotes globalmente sem saber qual interpretador o projeto usa."},{"type":"guided","question":"O que executa um arquivo .py?","options":["O interpretador Python.","O CSS.","O navegador por padrão."],"answer":0,"hint":"Escolha a alternativa que deixa o script mais previsível.","feedback":"Correto. A escolha preserva clareza e verificabilidade.","feedback_incorrect":"Revise o exemplo e a responsabilidade da estrutura."},{"type":"recap","items":["Explicar como o interpretador Python executa um script e preparar um fluxo simples de edição, execução e leitura de erros.","Confirme a versão ativa.","Execute scripts a partir do diretório correto.","Leia traceback de baixo para cima."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=7) and title='Python e o interpretador';
update nexora.lessons set objective='Declarar variáveis, trabalhar com tipos básicos e converter entrada textual antes de cálculos e comparações.',estimated_minutes=36,lab_type='python',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"input() retorna ''18'', e o programa precisa comparar idade numericamente."},{"type":"concept","title":"Variáveis, tipos e entrada de dados","body":"Python associa nomes a valores e possui tipos como int, float, str e bool. input() retorna texto, então conversão explícita é parte da modelagem. Operações entre tipos incompatíveis geram erros em vez de coerções silenciosas comuns em outras linguagens. Isso ajuda, desde que o programador trate entrada inválida."},{"type":"mechanics","title":"Como aplicar","items":["Use nomes descritivos.","Converta entrada antes de operar.","Valide antes de assumir formato.","Use type apenas como diagnóstico, não como arquitetura."]},{"type":"example","title":"Exemplo","body":"idade = int(input(''Idade: ''))\\nmaior = idade >= 18","language":"python"},{"type":"mistake","title":"Erro comum","body":"Fazer int(input()) sem tratar o caso em que o usuário digita texto inválido em um fluxo que precisa ser robusto."},{"type":"guided","question":"Qual tipo input() retorna inicialmente?","options":["str","int sempre","bool"],"answer":0,"hint":"Escolha a alternativa que deixa o script mais previsível.","feedback":"Correto. A escolha preserva clareza e verificabilidade.","feedback_incorrect":"Revise o exemplo e a responsabilidade da estrutura."},{"type":"recap","items":["Declarar variáveis, trabalhar com tipos básicos e converter entrada textual antes de cálculos e comparações.","Use nomes descritivos.","Converta entrada antes de operar.","Valide antes de assumir formato."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=7) and title='Variáveis, tipos e entrada de dados';
update nexora.lessons set objective='Implementar decisões com if/elif/else e operadores lógicos mantendo ramos legíveis e regras de fronteira corretas.',estimated_minutes=38,lab_type='python',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Uma nota precisa ser classificada em aprovado, recuperação ou reprovado sem sobreposição."},{"type":"concept","title":"Condições em Python","body":"Condições em Python usam blocos definidos por indentação. if testa o primeiro ramo; elif permite alternativas adicionais; else cobre o restante. A ordem importa: condições mais específicas ou fronteiras devem ser planejadas para que um caso não seja capturado cedo demais. Expressões booleanas podem ser nomeadas para melhorar leitura."},{"type":"mechanics","title":"Como aplicar","items":["Planeje faixas antes do código.","Teste fronteiras.","Mantenha indentação consistente.","Extraia condições complexas para nomes claros."]},{"type":"example","title":"Exemplo","body":"if nota >= 7:\\n    status=''Aprovado''\\nelif nota >= 5:\\n    status=''Recuperação''\\nelse:\\n    status=''Reprovado''","language":"python"},{"type":"mistake","title":"Erro comum","body":"Escrever vários if independentes para faixas mutuamente exclusivas e acabar sobrescrevendo o resultado."},{"type":"guided","question":"Quando os ramos são mutuamente exclusivos, qual estrutura é adequada?","options":["if/elif/else","Vários prints soltos","import"],"answer":0,"hint":"Escolha a alternativa que deixa o script mais previsível.","feedback":"Correto. A escolha preserva clareza e verificabilidade.","feedback_incorrect":"Revise o exemplo e a responsabilidade da estrutura."},{"type":"recap","items":["Implementar decisões com if/elif/else e operadores lógicos mantendo ramos legíveis e regras de fronteira corretas.","Planeje faixas antes do código.","Teste fronteiras.","Mantenha indentação consistente."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=7) and title='Condições em Python';
update nexora.lessons set objective='Escolher entre for e while e construir laços com condição de parada clara, contadores e acumuladores.',estimated_minutes=40,lab_type='python',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Uma lista precisa ser percorrida inteira; em outro caso, o programa repete até a entrada ser válida."},{"type":"concept","title":"Laços for e while","body":"for percorre iteráveis e é ideal quando existe uma coleção ou faixa. while repete enquanto uma condição permanece verdadeira, útil quando o número de repetições não é conhecido. Todo while precisa de uma mudança que aproxime o estado da condição de saída. break e continue existem, mas não devem esconder fluxo confuso."},{"type":"mechanics","title":"Como aplicar","items":["Use for para coleções e range.","Use while para repetição condicionada.","Garanta progresso em direção à parada.","Evite alterar coleção de forma imprevisível durante iteração."]},{"type":"example","title":"Exemplo","body":"for nome in nomes:\\n    print(nome)\\n\\ntentativas=0\\nwhile tentativas<3:\\n    tentativas+=1","language":"python"},{"type":"mistake","title":"Erro comum","body":"Criar while True e depender de vários breaks espalhados sem justificar o fluxo."},{"type":"guided","question":"Qual laço combina melhor com percorrer uma lista?","options":["for","while obrigatório","try"],"answer":0,"hint":"Escolha a alternativa que deixa o script mais previsível.","feedback":"Correto. A escolha preserva clareza e verificabilidade.","feedback_incorrect":"Revise o exemplo e a responsabilidade da estrutura."},{"type":"recap","items":["Escolher entre for e while e construir laços com condição de parada clara, contadores e acumuladores.","Use for para coleções e range.","Use while para repetição condicionada.","Garanta progresso em direção à parada."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=7) and title='Laços for e while';
update nexora.lessons set objective='Criar funções com parâmetros e retorno que concentrem regras e reduzam duplicação, evitando efeitos colaterais desnecessários.',estimated_minutes=42,lab_type='python',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"A mesma validação de preço aparece em três partes do script."},{"type":"concept","title":"Funções e retorno","body":"Funções em Python são definidas com def. Parâmetros representam entradas e return devolve uma saída. Funções pequenas e focadas podem ser testadas com diferentes casos sem depender de input() ou print(). Isso separa lógica da interface de terminal e prepara o código para módulos e testes."},{"type":"mechanics","title":"Como aplicar","items":["Uma função deve ter responsabilidade clara.","Receba dados por parâmetros.","Retorne resultado em vez de imprimir quando a saída será reutilizada.","Documente casos não óbvios."]},{"type":"example","title":"Exemplo","body":"def calcular_total(preco, quantidade):\\n    return preco * quantidade","language":"python"},{"type":"mistake","title":"Erro comum","body":"Misturar input(), cálculo, arquivo e print em uma função enorme."},{"type":"guided","question":"Qual função é mais reutilizável?","options":["Recebe parâmetros e retorna valor.","Lê tudo de globais.","Sempre encerra o programa."],"answer":0,"hint":"Escolha a alternativa que deixa o script mais previsível.","feedback":"Correto. A escolha preserva clareza e verificabilidade.","feedback_incorrect":"Revise o exemplo e a responsabilidade da estrutura."},{"type":"recap","items":["Criar funções com parâmetros e retorno que concentrem regras e reduzam duplicação, evitando efeitos colaterais desnecessários.","Uma função deve ter responsabilidade clara.","Receba dados por parâmetros.","Retorne resultado em vez de imprimir quando a saída será reutilizada."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=7) and title='Funções e retorno';
update nexora.lessons set objective='Usar listas para coleções mutáveis e tuplas para agrupamentos imutáveis simples, escolhendo operações adequadas.',estimated_minutes=42,lab_type='python',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Notas podem ser adicionadas durante o programa; uma coordenada fixa não deveria ser alterada."},{"type":"concept","title":"Listas e tuplas","body":"Listas são sequências mutáveis: permitem append, remoção e alteração. Tuplas são sequências imutáveis e expressam melhor conjuntos de valores que não devem mudar depois de criados. Ambas suportam iteração, indexação e slicing. A escolha comunica intenção e influencia como o código pode manipular o dado."},{"type":"mechanics","title":"Como aplicar","items":["Use lista para coleção que evolui.","Use tupla para agrupamento estável.","Evite depender de índices sem contexto.","Percorra diretamente quando não precisa do índice."]},{"type":"example","title":"Exemplo","body":"notas=[8,7,9]\\nnotas.append(10)\\nposicao=(12.3,-38.9)","language":"python"},{"type":"mistake","title":"Erro comum","body":"Usar índice mágico como registro complexo; para dados nomeados, dicionário ou dataclass pode ser melhor."},{"type":"guided","question":"Qual estrutura é mutável?","options":["list","tuple","str"],"answer":0,"hint":"Escolha a alternativa que deixa o script mais previsível.","feedback":"Correto. A escolha preserva clareza e verificabilidade.","feedback_incorrect":"Revise o exemplo e a responsabilidade da estrutura."},{"type":"recap","items":["Usar listas para coleções mutáveis e tuplas para agrupamentos imutáveis simples, escolhendo operações adequadas.","Use lista para coleção que evolui.","Use tupla para agrupamento estável.","Evite depender de índices sem contexto."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=7) and title='Listas e tuplas';
update nexora.lessons set objective='Modelar registros com dicionários e usar conjuntos para unicidade e operações de pertencimento eficientes.',estimated_minutes=44,lab_type='python',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Um usuário possui campos nomeados; uma lista de tags precisa eliminar duplicatas."},{"type":"concept","title":"Dicionários e conjuntos","body":"Dicionários mapeiam chaves a valores e são úteis para registros e índices. Sets armazenam valores únicos sem garantir ordem de apresentação como uma lista. Verificação de pertencimento em set costuma ser eficiente, e operações como união/interseção expressam relações entre coleções. Estruturas devem refletir a pergunta feita pelo programa."},{"type":"mechanics","title":"Como aplicar","items":["Use dict quando nomes de campos importam.","Use set para unicidade e pertencimento.","Trate chave ausente com get quando apropriado.","Não dependa de set para ordem de interface."]},{"type":"example","title":"Exemplo","body":"usuario={''nome'':''Ana'',''ativo'':True}\\ntags=set([''python'',''api'',''python''])","language":"python"},{"type":"mistake","title":"Erro comum","body":"Usar dict como lista ordenada de apresentação e depois depender de posições implícitas."},{"type":"guided","question":"Qual estrutura remove duplicatas naturalmente?","options":["set","list sempre","float"],"answer":0,"hint":"Escolha a alternativa que deixa o script mais previsível.","feedback":"Correto. A escolha preserva clareza e verificabilidade.","feedback_incorrect":"Revise o exemplo e a responsabilidade da estrutura."},{"type":"recap","items":["Modelar registros com dicionários e usar conjuntos para unicidade e operações de pertencimento eficientes.","Use dict quando nomes de campos importam.","Use set para unicidade e pertencimento.","Trate chave ausente com get quando apropriado."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=7) and title='Dicionários e conjuntos';
update nexora.lessons set objective='Normalizar, dividir, combinar e formatar strings sem destruir informação necessária ou criar regras frágeis.',estimated_minutes=40,lab_type='python',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Nomes chegam com espaços extras e e-mails com variação de maiúsculas, mas mensagens de saída precisam preservar formato legível."},{"type":"concept","title":"Strings e manipulação de texto","body":"Strings são sequências imutáveis. Métodos como strip, lower, split, replace e join ajudam a normalizar e transformar texto. f-strings criam saída legível. Normalização deve ser proporcional ao domínio: converter e-mail para comparação pode fazer sentido; alterar nome próprio agressivamente pode perder informação."},{"type":"mechanics","title":"Como aplicar","items":["Use strip para espaços externos.","Normalize apenas quando a regra justifica.","Use split/join para estruturas simples de texto.","Prefira f-strings para interpolação legível."]},{"type":"example","title":"Exemplo","body":"email = email.strip().lower()\\nmensagem = f''Olá, {nome}!''","language":"python"},{"type":"mistake","title":"Erro comum","body":"Aplicar lower/replace em todo texto sem considerar se capitalização ou símbolos têm significado."},{"type":"guided","question":"Qual método remove espaços nas extremidades?","options":["strip","append","keys"],"answer":0,"hint":"Escolha a alternativa que deixa o script mais previsível.","feedback":"Correto. A escolha preserva clareza e verificabilidade.","feedback_incorrect":"Revise o exemplo e a responsabilidade da estrutura."},{"type":"recap","items":["Normalizar, dividir, combinar e formatar strings sem destruir informação necessária ou criar regras frágeis.","Use strip para espaços externos.","Normalize apenas quando a regra justifica.","Use split/join para estruturas simples de texto."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=7) and title='Strings e manipulação de texto';
update nexora.lessons set objective='Ler e escrever arquivos usando context manager e pathlib, tratando codificação e caminhos de forma portátil.',estimated_minutes=46,lab_type='python',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O script funciona apenas quando executado de uma pasta específica porque usa caminhos relativos frágeis."},{"type":"concept","title":"Arquivos e caminhos","body":"Arquivos introduzem estado fora da memória. open com with garante fechamento mesmo em caso de erro. pathlib oferece objetos Path para montar caminhos de forma mais clara e portátil. A codificação deve ser explícita quando texto é relevante. Antes de sobrescrever, decida se o fluxo precisa preservar ou versionar o arquivo existente."},{"type":"mechanics","title":"Como aplicar","items":["Use with ao abrir arquivos.","Prefira pathlib para caminhos.","Declare encoding em texto.","Valide existência e destino antes de escrita destrutiva."]},{"type":"example","title":"Exemplo","body":"from pathlib import Path\\narq=Path(''dados'')/''clientes.txt''\\nwith arq.open(''r'',encoding=''utf-8'') as f:\\n    texto=f.read()","language":"python"},{"type":"mistake","title":"Erro comum","body":"Montar caminhos concatenando barras específicas do sistema operacional."},{"type":"guided","question":"Qual recurso ajuda a construir caminhos portáveis?","options":["pathlib.Path","print","range"],"answer":0,"hint":"Escolha a alternativa que deixa o script mais previsível.","feedback":"Correto. A escolha preserva clareza e verificabilidade.","feedback_incorrect":"Revise o exemplo e a responsabilidade da estrutura."},{"type":"recap","items":["Ler e escrever arquivos usando context manager e pathlib, tratando codificação e caminhos de forma portátil.","Use with ao abrir arquivos.","Prefira pathlib para caminhos.","Declare encoding em texto."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=7) and title='Arquivos e caminhos';
update nexora.lessons set objective='Capturar exceções específicas quando existe estratégia de recuperação e evitar esconder falhas inesperadas.',estimated_minutes=46,lab_type='python',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Uma conversão pode falhar, mas um except: vazio está engolindo também bugs de programação."},{"type":"concept","title":"Tratamento de erros","body":"Exceções interrompem o fluxo normal e carregam informação sobre falha. try/except deve envolver apenas a operação esperadamente arriscada. Capture tipos específicos e decida se há recuperação, mensagem ao usuário ou repropagação. finally serve para limpeza quando necessária. Capturar Exception em toda parte costuma esconder causa."},{"type":"mechanics","title":"Como aplicar","items":["Capture exceções específicas.","Mantenha bloco try pequeno.","Não silencie erro sem registrar ou tratar.","Use mensagem adequada ao usuário sem expor stack interno."]},{"type":"example","title":"Exemplo","body":"try:\\n    idade=int(texto)\\nexcept ValueError:\\n    print(''Informe um número inteiro.'')","language":"python"},{"type":"mistake","title":"Erro comum","body":"except: pass. O programa continua em estado possivelmente inválido sem qualquer diagnóstico."},{"type":"guided","question":"Qual exceção ocorre tipicamente em int(''abc'')?","options":["ValueError","KeyError sempre","ImportError"],"answer":0,"hint":"Escolha a alternativa que deixa o script mais previsível.","feedback":"Correto. A escolha preserva clareza e verificabilidade.","feedback_incorrect":"Revise o exemplo e a responsabilidade da estrutura."},{"type":"recap","items":["Capturar exceções específicas quando existe estratégia de recuperação e evitar esconder falhas inesperadas.","Capture exceções específicas.","Mantenha bloco try pequeno.","Não silencie erro sem registrar ou tratar."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=7) and title='Tratamento de erros';
update nexora.lessons set objective='Organizar código em módulos, importar responsabilidades e isolar dependências do projeto em ambiente virtual.',estimated_minutes=50,lab_type='python',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Dois projetos precisam de versões diferentes da mesma biblioteca e ambos usam instalação global."},{"type":"concept","title":"Módulos, pacotes e ambiente virtual","body":"Módulos são arquivos Python importáveis; pacotes agrupam módulos. Ambientes virtuais isolam dependências por projeto, evitando conflito com instalações globais. requirements ou pyproject documentam dependências. A organização deve nascer de responsabilidades reais, não de criar dezenas de arquivos minúsculos sem necessidade."},{"type":"mechanics","title":"Como aplicar","items":["Crie venv por projeto.","Registre dependências.","Separe módulos por responsabilidade.","Evite import circular."]},{"type":"example","title":"Exemplo","body":"python -m venv .venv\\n# ativar ambiente\\npip install requests","language":"python"},{"type":"mistake","title":"Erro comum","body":"Instalar tudo globalmente e descobrir depois que o projeto só funciona na máquina do autor."},{"type":"guided","question":"Qual é o objetivo principal de um ambiente virtual?","options":["Isolar dependências do projeto.","Aumentar resolução da tela.","Substituir Git."],"answer":0,"hint":"Escolha a alternativa que deixa o script mais previsível.","feedback":"Correto. A escolha preserva clareza e verificabilidade.","feedback_incorrect":"Revise o exemplo e a responsabilidade da estrutura."},{"type":"recap","items":["Organizar código em módulos, importar responsabilidades e isolar dependências do projeto em ambiente virtual.","Crie venv por projeto.","Registre dependências.","Separe módulos por responsabilidade."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=7) and title='Módulos, pacotes e ambiente virtual';
update nexora.lessons set objective='Automatizar uma tarefa repetitiva com entradas, validação, processamento e relatório, mantendo operação idempotente quando possível.',estimated_minutes=52,lab_type='python',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Todo dia alguém lê uma pasta de arquivos, renomeia e gera um resumo manualmente."},{"type":"concept","title":"Automação de tarefas","body":"Automação útil transforma um processo repetível em sequência previsível. Primeiro modele entradas e saídas; depois trate erros e reexecução. Um script idempotente pode ser executado novamente sem duplicar ou corromper resultado, característica valiosa em tarefas operacionais. Logs simples ajudam a entender o que aconteceu."},{"type":"mechanics","title":"Como aplicar","items":["Automatize processo estável e compreendido.","Valide arquivos antes de alterar.","Planeje reexecução.","Produza relatório ou log do resultado."]},{"type":"example","title":"Exemplo","body":"for arquivo in pasta.glob(''*.csv''):\\n    processar(arquivo)\\nprint(''Processamento concluído'')","language":"python"},{"type":"mistake","title":"Erro comum","body":"Automatizar um processo mal definido e acelerar erros que antes eram manuais."},{"type":"guided","question":"O que significa uma automação idempotente?","options":["Pode ser repetida sem duplicar o efeito indevidamente.","Só roda uma vez.","Nunca registra logs."],"answer":0,"hint":"Escolha a alternativa que deixa o script mais previsível.","feedback":"Correto. A escolha preserva clareza e verificabilidade.","feedback_incorrect":"Revise o exemplo e a responsabilidade da estrutura."},{"type":"recap","items":["Automatizar uma tarefa repetitiva com entradas, validação, processamento e relatório, mantendo operação idempotente quando possível.","Automatize processo estável e compreendido.","Valide arquivos antes de alterar.","Planeje reexecução."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=7) and title='Automação de tarefas';
update nexora.lessons set objective='Consumir uma API HTTP em Python tratando timeout, status, JSON e falhas de rede antes de usar os dados.',estimated_minutes=52,lab_type='api',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Um script depende de serviço externo e trava indefinidamente quando a rede está ruim."},{"type":"concept","title":"Consumo de APIs com Python","body":"Bibliotecas HTTP permitem enviar requisições, mas integração robusta precisa de timeout, verificação de status e validação do payload. Serviços externos falham e podem retornar formato inesperado. O código deve separar transporte, parsing e regra de negócio para que erros sejam diagnósticos."},{"type":"mechanics","title":"Como aplicar","items":["Defina timeout.","Verifique status HTTP.","Valide campos essenciais do JSON.","Trate falha externa sem corromper dados locais."]},{"type":"example","title":"Exemplo","body":"import requests\\nr=requests.get(url,timeout=10)\\nr.raise_for_status()\\ndata=r.json()","language":"python"},{"type":"mistake","title":"Erro comum","body":"Chamar API em loop sem timeout, retry controlado ou limite."},{"type":"guided","question":"Qual parâmetro evita esperar indefinidamente por uma resposta?","options":["timeout","print","len"],"answer":0,"hint":"Escolha a alternativa que deixa o script mais previsível.","feedback":"Correto. A escolha preserva clareza e verificabilidade.","feedback_incorrect":"Revise o exemplo e a responsabilidade da estrutura."},{"type":"recap","items":["Consumir uma API HTTP em Python tratando timeout, status, JSON e falhas de rede antes de usar os dados.","Defina timeout.","Verifique status HTTP.","Valide campos essenciais do JSON."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=7) and title='Consumo de APIs com Python';
update nexora.lessons set objective='Construir uma automação Python que lide com arquivos ou API, registre resultado e possa ser executada por outra pessoa com instruções claras.',estimated_minutes=70,lab_type='project',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"A entrega deve economizar trabalho real e não apenas imprimir exemplos no terminal."},{"type":"concept","title":"Projeto: automação útil do mundo real","body":"O projeto fecha Python combinando estruturas, funções, arquivos, erros, módulos e integração. Escolha uma tarefa pequena e frequente: consolidar planilhas, organizar arquivos, consultar API e gerar relatório, validar dados. A automação precisa ter entradas claras, comportamento em erro, reexecução segura e documentação de ambiente."},{"type":"mechanics","title":"Como aplicar","items":["Escolha problema real e mensurável.","Separe configuração de código.","Trate erros previsíveis.","Documente instalação e execução."]},{"type":"example","title":"Exemplo","body":"Exemplo: ler CSVs de uma pasta, normalizar colunas, consolidar registros válidos e gerar relatório de inconsistências."},{"type":"mistake","title":"Erro comum","body":"Criar automação que exige editar o código toda vez para trocar caminho, chave ou parâmetro."},{"type":"guided","question":"Qual característica torna a automação útil para terceiros?","options":["Configuração e execução documentadas.","Dependência de caminhos pessoais fixos.","Ausência de tratamento de erro."],"answer":0,"hint":"Escolha a alternativa que deixa o script mais previsível.","feedback":"Correto. A escolha preserva clareza e verificabilidade.","feedback_incorrect":"Revise o exemplo e a responsabilidade da estrutura."},{"type":"recap","items":["Construir uma automação Python que lide com arquivos ou API, registre resultado e possa ser executada por outra pessoa com instruções claras.","Escolha problema real e mensurável.","Separe configuração de código.","Trate erros previsíveis."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=7) and title='Projeto: automação útil do mundo real';

